+package com.example;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.example.views.ContactView;
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void validatesSendsAndGuards() {
+        navigate(ContactView.class);
+        test($(Button.class).withText("Send").single()).click();
+        assertEquals("Name is required",
+                $(TextField.class).withCaption("Name").single().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number",
+                $(EmailField.class).single().getErrorMessage());
+
+        test($(TextField.class).withCaption("Name").single()).setValue("A");
+        test($(TextField.class).withCaption("Phone").single()).setValue("1");
+        test($(com.vaadin.flow.component.textfield.TextArea.class).single()).setValue("hi");
+        test($(Button.class).withText("Send").single()).click();
+        assertFalse($(Button.class).withText("Send").single().isEnabled());
+        assertTrue($(TextField.class).withCaption("Name").single().isEmpty());
+
+        test($(TextField.class).withCaption("Name").single()).setValue("B");
+        assertTrue($(Button.class).withText("Send").single().isEnabled());
+        com.vaadin.flow.component.UI.getCurrent().navigate("about");
+        assertEquals(1, $(Dialog.class).all().size());
+    }
+}
